def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse history.
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    # Counts and rates.
    opp_c = 0
    opp_d = 0
    for b in opp:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    opp_rate = opp_c / n

    # Considers exploitability of naive opponents near the end.
    remaining = 100 - n

    # Early game: cooperate to permit mutual cooperation.
    if n < 3:
        return 'C'

    # Detect pure/near-pure defectors and defend strongly.
    if opp_c == 0:
        return 'D'
    if n >= 6 and opp_c == 1 and remaining > 4:
        return 'D'
    if n >= 12 and opp_rate <= 0.15:
        return 'D'
    if n >= 12 and opp_rate <= 0.3:
        # Mostly defecting: defect, with occasional probing to test renewal.
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Opponent just defected: respond. Short punishment, then offer recovery.
    if last_opp == 'D':
        # Count trailing opponent defection streak.
        streak = 0
        idx = n - 1
        while idx >= 0 and opp[idx] == 'D':
            streak += 1
            idx -= 1

        # If we have been in mutual defection, occasionally offer olive branch.
        if last_me == 'D':
            if streak >= 3:
                # Try to break deadlock with some probability.
                if rng.random() < 0.2:
                    return 'C'
                return 'D'
            # Short mutual defection: continue punishing briefly then forgive.
            return 'D'

        # We were cooperating and got hit.
        if streak == 1:
            # Single defection: punish once, don't spiral.
            return 'D'
        if streak == 2:
            # Second defection: keep punishing, but consider a reset soon.
            if opp_rate > 0.6 and rng.random() < 0.4:
                return 'C'
            return 'D'
        # Long streak: mostly defect, rare probe.
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if n < 10:
        return 'C'

    # Strong mutual cooperation — preserve it, but consider late exploitation.
    if opp_rate >= 0.85:
        if remaining <= 2:
            # Very last rounds against a high cooperator: take payoff.
            if opp_rate >= 0.9:
                return 'D'
            return 'C'
        if remaining <= 6:
            # Near end, exploit a reliable cooperator a bit.
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        if remaining <= 12:
            if rng.random() < 0.2:
                return 'D'
            return 'C'
        return 'C'

    # Recent behavior via last 10 rounds.
    window = 10 if n >= 10 else n
    recent = opp[-window:]
    recent_c = 0
    for b in recent:
        if b == 'C':
            recent_c += 1
    recent_rate = recent_c / window

    # Opponent cooperative recently but overall mixed: reciprocate and forgive.
    if recent_rate >= 0.8:
        # If highly cooperative but not pure, cautiously maintain.
        if remaining <= 8 and opp_rate >= 0.75:
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        return 'C'

    if recent_rate >= 0.5:
        # Mixed but leaning cooperative: cooperate, avoid needless conflict.
        if last_me == 'D':
            # We just defected; return to cooperation to repair.
            return 'C'
        return 'C'

    # Opponent mixed but leaning defective recently.
    if recent_rate >= 0.3:
        # Use tit-for-tat-like response with forgiveness.
        if last_me == 'C' and last_opp == 'C':
            return 'C'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Opponent recently defecting a lot.
    if remaining <= 6:
        return 'D'
    if rng.random() < 0.08:
        return 'C'
    return 'D'
